import{_ as s,o as t,c as o,a2 as a}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"ADR 0005 — WebView loads server.url, never bundled capacitor:// assets","description":"","frontmatter":{"status":"Accepted","date":"2026-07-31T00:00:00.000Z","deciders":"kasunben","sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/0005-server-url-not-bundled-assets.md"},"headers":[],"relativePath":"apps/mobile/adrs/0005-server-url-not-bundled-assets.md","filePath":"apps/mobile/adrs/0005-server-url-not-bundled-assets.md"}'),r={name:"apps/mobile/adrs/0005-server-url-not-bundled-assets.md"};function i(n,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0005-—-webview-loads-server-url-never-bundled-capacitor-assets" tabindex="-1">ADR 0005 — WebView loads <code>server.url</code>, never bundled <code>capacitor://</code> assets <a class="header-anchor" href="#adr-0005-—-webview-loads-server-url-never-bundled-capacitor-assets" aria-label="Permalink to &quot;ADR 0005 — WebView loads `server.url`, never bundled `capacitor://` assets&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted. Locked by sovereign workstream 0002&#39;s &quot;Decisions locked&quot; table, contingent on the offline spike in <a href="./../epics/shell.html">epics/shell.md</a> (task 20.10) measuring the actual tradeoff before implementation.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Capacitor can serve WebView content two ways: bundled local assets over the custom <code>capacitor://</code> scheme, or a remote origin over <code>https</code> via <code>server.url</code>. The choice determines whether a service worker — and therefore any offline behavior at all — is possible.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Point Capacitor&#39;s <code>server.url</code> at the user&#39;s remote instance over <code>https</code>.</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Bundled local assets over <code>capacitor://</code>.</strong> Service workers require a secure-context document. On iOS, the <code>capacitor://</code> custom scheme yields <strong>no service worker at all</strong> — <code>navigator.serviceWorker</code> isn&#39;t even exposed, confirmed empirically by <a href="https://github.com/sovereignfs/sovereign/blob/main/docs/research/0008-wkwebview-android-webview-offline-spike.md" target="_blank" rel="noreferrer">sovereign research 0008</a>. This foreclosing-offline-entirely outcome is the load-bearing reason this ADR exists. <strong>Correction (2026-08-02):</strong> that same research also found this is iOS-specific, not a cross-platform fact as originally stated here — Android&#39;s default bundled scheme (<code>androidScheme: &quot;https&quot;</code>, i.e. <code>https://localhost</code>) <strong>does</strong> support service workers. This doesn&#39;t change the decision (see Consequences: the real justification is <a href="./0002-universal-one-binary-distribution.html">ADR 0002</a>&#39;s &quot;no baked-in instance,&quot; which applies regardless of what either platform&#39;s bundled scheme supports — a self-hosted, runtime-chosen instance genuinely cannot be baked into a build), only this stated rationale.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The shell has no meaningfully useful offline-first bundle of its own — it is a thin loader for a remote origin, consistent with <a href="./0002-universal-one-binary-distribution.html">ADR 0002</a>&#39;s &quot;no baked-in instance&quot; decision.</li><li>Actual offline scope (what works without connectivity, what doesn&#39;t) is determined empirically by the WKWebView offline spike (task 20.10), not assumed. See <a href="./../epics/shell.html">epics/shell.md</a> leg detail.</li><li>Any future bundled-asset approach would need its own ADR revisiting this one, since it reopens the offline-support question this ADR closes.</li></ul>',11)])])}const b=s(r,[["render",i]]);export{p as __pageData,b as default};
